broll.usage:
// Load runtime/appearance.js, runtime/rolls.js and runtime/broll.js first.
import {mount} from './vendor/components/synthetic-broll/v1/main.js';
const appearance = await HarnessAppearance.load();
const cues = {find: key => ({sceneStart:0, shotStart:1, shotEnd:4, sceneEnd:5})[key]};
const shot = await mount({stage, text, appearance, slots:{title:'Broll signal', value:42}, params:{}, startCue:'shotStart', endCue:'shotEnd', cues});
const rolls = HarnessRolls.mount({cues, scenes:[{id:'broll', startCue:'sceneStart', endCue:'sceneEnd', a:{text:aText, items:[{id:'a1', element:aItem, cue:'sceneStart'}]}, b:[{startCue:'shotStart', endCue:'shotEnd', retreat:'hide', media:stage, text}]}]});
async function renderAt(t) {shot.renderAt(t); await rolls.renderAt(t);}
await renderAt(2.5);
const {key_moments, sfx_cues} = shot.moments();
function dispose() {shot.dispose(); rolls.dispose(); appearance.dispose();}
